const API_URL="https://app-70zj.onrender.com";const cpfAdm=localStorage.getItem("cpfAdm");document.addEventListener("DOMContentLoaded",()=>{const form=document.getElementById("config-form");const configSalva=JSON.parse(localStorage.getItem("configBoletos"));if(configSalva){document.getElementById("diaLiberacao").value=configSalva.diaLiberacao||"";document.getElementById("diaVencimento").value=configSalva.diaVencimento||"";document.getElementById("valorPadrao").value=configSalva.valorPadrao||""}form.addEventListener("submit",async e=>{e.preventDefault();const config={diaLiberacao:parseInt(document.getElementById("diaLiberacao").value),diaVencimento:parseInt(document.getElementById("diaVencimento").value),valorPadrao:document.getElementById("valorPadrao").value};if(!config.diaLiberacao||!config.diaVencimento||!config.valorPadrao){alert("Preencha todos os campos.");return}localStorage.setItem("configBoletos",JSON.stringify(config));try{await fetch(`${API_URL}/usuarios/${cpfAdm}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({configBoletos:config})});alert("Configurações salvas com sucesso!");window.location.href="adm.html"}catch(err){console.error("Erro ao salvar no backend:",err);alert("Erro ao salvar no servidor.")}})});